{"command":"$ErrorActionPreference='Continue'
foreach ($u in @('https://jevfast.com/creative/','https://jevai.dev/ru/playground/')) {
  Write-Output "===== $u ====="
  try {
    $r = Invoke-WebRequest -Uri $u -UseBasicParsing -TimeoutSec 25
    $txt = $r.Content -replace '<script[\s\S]*?</script>','' -replace '<style[\s\S]*?</style>','' -replace '<[^>]+>',' ' -replace '\s+',' '
    Write-Output $txt.Substring(0, [Math]::Min(3000, $txt.Length))
  } catch { Write-Output "FAIL: $($_.Exception.Message)" }
}","description":"Fetch Jev community and playground pages","timeout":90}

{"command":"$ErrorActionPreference='Continue'
function Probe($name,$url,$method='GET',$body=$null){
  try{
    $p = @{Uri=$url;Method=$method;TimeoutSec=15;ErrorAction='Stop'}
    if($body){$p.Body=$body;$p.ContentType='application/json';$p.Headers=@{Authorization='Bearer test'}}
    $r=Invoke-WebRequest @p
    Write-Output "$name -> $($r.StatusCode) $($r.Content.Substring(0,[Math]::Min(300,$r.Content.Length)))"
  }catch{
    $code = try{ [int]$_.Exception.Response.StatusCode }catch{ 'n/a' }
    $msg = try{ $_.ErrorDetails.Message }catch{ $_.Exception.Message }
    Write-Output "$name -> ERR($code): $msg"
  }
}
